const std = @import("std");

fn fibMemo(n: u32, memo: []u64) u64 {
    if (n <= 1) return n;
    if (memo[n] != 0) return memo[n];
    memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
    return memo[n];
}

pub fn main() !void {
    var memo = [_]u64{0} ** 50;
    const n: u32 = 40;
    const result = fibMemo(n, &memo);
    std.debug.print("fib({}) = {}\n", .{n, result});
}

